// Regla del proyecto: nunca atribuir una frase a una persona sin
// evidencia suficiente. Si el nodo de diarizacion de arriba no esta
// configurado (o no devuelve una etiqueta de hablante confiable),
// se marca speaker = 'unidentified'.
const diarization = items[0].json.speaker_label || null;
const trigger = $('Execute Workflow Trigger').item.json;
return [{ json: {
  meeting_id: trigger.meeting_id,
  timestamp: trigger.timestamp,
  text: trigger.text,
  speaker: diarization || 'unidentified',
  requires_manual_labeling: !diarization,
}}];
